function shrink(a: f64[], v: ReadSpan<f64>): ReadSpan<f64> {
  a.length = 0;
  return v;
}
export function entry(): f64 {
  const a: f64[] = [1];
  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  const w: ReadSpan<f64> = shrink(a, v);
  a[2] = 1;
  return 1;
}

